package net.zartra.gui;
import org.bukkit.configuration.ConfigurationSection; import org.bukkit.configuration.file.YamlConfiguration; import java.io.*; import java.util.*; import java.util.logging.Logger;
public final class MenuStorage {
 private final File folder; private final Logger log; public MenuStorage(File f,Logger l){folder=f;log=l;}
 public Map<String,MenuDefinition> load(){Map<String,MenuDefinition> all=new HashMap<String,MenuDefinition>(); if(!folder.exists())folder.mkdirs(); File[] fs=folder.listFiles();if(fs==null)return all; for(File f:fs)if(f.getName().endsWith(".yml"))try{YamlConfiguration y=YamlConfiguration.loadConfiguration(f);String id=y.getString("id");if(!MenuManager.validId(id)){log.warning("Ignoring invalid menu file: "+f.getName());continue;} MenuDefinition d=new MenuDefinition(id,y.getString("title","Menu"),y.getInt("rows",1));d.command(y.getString("opening-command",""));ConfigurationSection items=y.getConfigurationSection("items");if(items!=null)for(String k:items.getKeys(false))try{int slot=Integer.parseInt(k);MenuItemDefinition x=MenuItemDefinition.load(items.getConfigurationSection(k));if(x!=null&&slot>=0&&slot<d.rows()*9)d.items().put(slot,x);}catch(NumberFormatException ignored){} all.put(id,d);}catch(Exception e){log.warning("Could not load menu "+f.getName()+": "+e.getMessage());} return all;}
 public void save(MenuDefinition d) throws IOException {if(!folder.exists()&&!folder.mkdirs())throw new IOException("Cannot create menus directory");YamlConfiguration y=new YamlConfiguration();y.set("id",d.id());y.set("title",d.title());y.set("rows",d.rows());y.set("opening-command",d.command());for(Map.Entry<Integer,MenuItemDefinition> e:d.items().entrySet())e.getValue().save(y.createSection("items."+e.getKey()));File tmp=new File(folder,d.id()+".yml.tmp"),out=new File(folder,d.id()+".yml");y.save(tmp);if(out.exists()&&!out.delete())throw new IOException("Cannot replace menu file");if(!tmp.renameTo(out))throw new IOException("Cannot rename menu file");}
 public boolean delete(String id){File f=new File(folder,id+".yml");return !f.exists()||f.delete();}
}
